-- =====================================================================
-- 502_asset_fields_taxonomy_templates_load.sql
--
-- A DATA LOAD, not a schema change. Nothing is created, altered or
-- dropped: every table, procedure and constraint it uses already exists
-- (420 field dictionary + form templates, 239/002 asset taxonomy,
-- 035 state machine).
--
-- SOURCE
-- ------
--   AssetFields_Mapping_v1.0.xlsx, three sheets:
--     Sheet1        270 field-dictionary rows  -> asset_field_definition
--     Asset Types   318 rows (11 categories, 52 subcategories)
--                   -> dependency_asset_category_master
--                      dependency_asset_subcategory_master
--                      dependency_asset_type_master
--                   and its required_display_labels /
--                   conditional_display_labels /
--                   system_managed_display_labels columns
--                   -> asset_form_template(+ _section, _field)
--     Mapping Rules notes only; not loaded.
--
--   Every one of the 47,249 label references in the sheet was checked
--   against the dictionary before this file was written: all 270 labels
--   are unique, all 47,249 references resolve, no label appears under
--   two kinds for the same asset type, and all 10 is_system_mandatory
--   fields appear in every profile. So no reference can be dropped
--   silently here.
--
--   The 318 asset types share only 34 distinct label sets, so the sheet
--   is carried below as 34 profiles (#profile_field) plus a 318-row
--   asset-type-to-profile map, instead of 47,249 literal rows.
--
-- WHAT IT DOES
-- ------------
--   1. GUARDS. Refuses to run, changing nothing, when
--        * a required table or the 420 seed is missing, or
--        * asset_field_value holds rows -- that table IS registered
--          asset data (one row per asset per field) and it is the
--          cascade behind re-seeding the dictionary. Set @force_delete_
--          asset_values = 1 to override, which DESTROYS those values.
--   2. FIELD DICTIONARY. Deletes every asset form template (all
--      organizations), its rules, sections and fields, then deletes
--      asset_field_definition, reseeds its identity and re-inserts the
--      sheet's 270 rows with their own field_definition_id 1-270
--      (IDENTITY_INSERT), so the ids match the sheet exactly.
--      field_group_id is resolved through asset_field_group_master.
--      group_code -- never by trusting identity values.
--   3. TAXONOMY. Sets is_active = 0 on every existing category,
--      subcategory and asset type, then MERGEs the sheet's 11 / 52 / 318
--      on their codes as is_active = 1. Nothing is deleted: the old ids
--      are referenced by organization_dependency_asset, the event scope
--      mapping (123/127/136) and the technology / firmware / OS catalogs
--      (425/426/427), and deactivating keeps every one of those rows
--      valid while removing the old values from the pickers.
--   4. TEMPLATES. One ACTIVE, version-1 asset form template per
--      organization per asset type, with a section per dictionary group
--      that has fields (plus AUDIT_HISTORY, exactly as
--      sp_asset_form_template_create does), and one
--      asset_form_template_field per label:
--        required          is_visible 1, is_mandatory 1
--        conditional       is_visible 1, is_mandatory 0
--        system-managed    is_visible 1, is_mandatory 0, is_read_only 1
--      with one override: any is_system_mandatory field is forced
--      mandatory, because 420 forbids weakening the 5.1.17 baseline and
--      its readiness check enforces it. Only Asset ID and Asset status
--      are affected -- the sheet puts those two under system-managed --
--      and both come out mandatory AND read-only, which is what
--      sp_asset_form_template_create produces for them as well.
--      is_read_only is also set for any field whose data type is not
--      user-entered (dt.is_user_entered = 0), the rule 420's own create
--      procedure uses. Each template gets an entity_state_transition_log
--      row (NULL -> ACTIVE, reason BULK_LOAD; the framework allows a
--      NULL from_status and a NULL actor for a system actor) and a
--      practice_audit_trace row, so the load is auditable.
--
-- OPERATOR SWITCHES -- set them in section 0 below.
--
-- ONE TRANSACTION. Either all of it lands or none of it does.
-- SAFE TO RE-RUN: it clears what it owns before re-inserting.
-- ASCII-only. No GO inside the load, so the switches stay in scope.
-- Rollback: 502_asset_fields_taxonomy_templates_load_rollback.sql
-- =====================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

-- =====================================================================
-- 0. Operator switches
-- =====================================================================
DECLARE @organization_id BIGINT = NULL;   -- NULL = every ACTIVE organization
DECLARE @actor           NVARCHAR(100) = N'load-502';
DECLARE @template_status NVARCHAR(20)  = N'ACTIVE';   -- or N'DRAFT'
DECLARE @force_delete_asset_values BIT = 0;           -- 1 DESTROYS asset field values
-- organization_dependency_asset.template_id records which form template
-- version an asset was registered with (428). Deleting every template, as
-- asked, has to clear that link first -- the column is nullable and there
-- is nowhere else for it to point. 1 clears it and reports the count;
-- 0 makes the script abort instead, leaving everything alone.
DECLARE @clear_asset_template_links BIT = 1;

-- =====================================================================
-- 1. Guards
-- =====================================================================
DECLARE @msg NVARCHAR(2048);

IF OBJECT_ID('grac_practice.asset_field_definition','U')     IS NULL
   OR OBJECT_ID('grac_practice.asset_field_group_master','U') IS NULL
   OR OBJECT_ID('grac_practice.asset_field_data_type_master','U') IS NULL
   OR OBJECT_ID('grac_practice.asset_form_template','U')      IS NULL
   OR OBJECT_ID('grac_practice.asset_form_template_section','U') IS NULL
   OR OBJECT_ID('grac_practice.asset_form_template_field','U')   IS NULL
   OR OBJECT_ID('grac_practice.dependency_asset_category_master','U')    IS NULL
   OR OBJECT_ID('grac_practice.dependency_asset_subcategory_master','U') IS NULL
   OR OBJECT_ID('grac_practice.dependency_asset_type_master','U')        IS NULL
   OR OBJECT_ID('grac_practice.fn_get_entity_status_id','FN')            IS NULL
BEGIN
    RAISERROR('ABORT (502): run 239, 240 and 420 first.', 16, 1);
    RETURN;
END

IF (SELECT COUNT(*) FROM grac_practice.asset_field_group_master) < 14
BEGIN
    RAISERROR('ABORT (502): asset_field_group_master has fewer than the 14 groups 420 seeds.', 16, 1);
    RETURN;
END

IF grac_practice.fn_get_entity_status_id(N'AssetFormTemplate', @template_status) IS NULL
BEGIN
    SET @msg = N'ABORT (502): AssetFormTemplate status ' + @template_status + N' is not in entity_status_master.';
    RAISERROR(@msg, 16, 1);
    RETURN;
END

IF @organization_id IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM grac_practice.organization WHERE organization_id = @organization_id)
BEGIN
    RAISERROR('ABORT (502): the organization in @organization_id does not exist.', 16, 1);
    RETURN;
END

-- The cascade that matters. asset_field_value is asset DATA.
DECLARE @value_rows BIGINT = 0;
IF OBJECT_ID('grac_practice.asset_field_value','U') IS NOT NULL
    SELECT @value_rows = COUNT_BIG(*) FROM grac_practice.asset_field_value;

IF @value_rows > 0 AND @force_delete_asset_values = 0
BEGIN
    SET @msg = N'ABORT (502): asset_field_value holds ' + CAST(@value_rows AS NVARCHAR(20))
             + N' row(s) of registered asset data. Re-seeding the field dictionary would delete them. '
             + N'Nothing was changed. Set @force_delete_asset_values = 1 only if that loss is intended.';
    RAISERROR(@msg, 16, 1);
    RETURN;
END


-- =====================================================================
-- 2. Staging
-- =====================================================================
CREATE TABLE #field_def (
    field_definition_id  INT            NOT NULL PRIMARY KEY,
    field_key            NVARCHAR(100)  NOT NULL,
    display_label        NVARCHAR(200)  NOT NULL,
    group_code           NVARCHAR(60)   NOT NULL,
    data_type_code       NVARCHAR(30)   NOT NULL,
    lookup_source        NVARCHAR(100)  NULL,
    validation_rule_text NVARCHAR(1000) NULL,
    description          NVARCHAR(1000) NULL,
    is_system_mandatory  BIT            NOT NULL,
    is_system_field      BIT            NOT NULL,
    storage_kind         NVARCHAR(10)   NOT NULL,
    column_name          NVARCHAR(128)  NULL,
    sensitivity_code     NVARCHAR(20)   NOT NULL,
    display_order        INT            NOT NULL,
    definition_version   INT            NOT NULL,
    effective_from       DATE           NOT NULL,
    effective_to         DATE           NULL,
    status_code          NVARCHAR(20)   NOT NULL,
    is_custom            BIT            NOT NULL
);

CREATE TABLE #category (
    category_name NVARCHAR(160) NOT NULL PRIMARY KEY,
    category_code NVARCHAR(60)  NOT NULL,
    display_order INT           NOT NULL
);

CREATE TABLE #subcategory (
    category_name    NVARCHAR(160) NOT NULL,
    subcategory_name NVARCHAR(200) NOT NULL,
    subcategory_code NVARCHAR(80)  NOT NULL,
    display_order    INT           NOT NULL,
    PRIMARY KEY (category_name, subcategory_name)
);

CREATE TABLE #asset_type (
    category_name    NVARCHAR(160) NOT NULL,
    subcategory_name NVARCHAR(200) NOT NULL,
    asset_type_name  NVARCHAR(200) NOT NULL,
    asset_type_code  NVARCHAR(80)  NOT NULL PRIMARY KEY,
    display_order    INT           NOT NULL,
    profile_no       INT           NOT NULL
);

-- One row per (label set, label, kind) -- the sheet's three columns,
-- already split, for the 34 distinct label sets.
CREATE TABLE #profile_field (
    profile_no    INT           NOT NULL,
    display_label NVARCHAR(200) NOT NULL,
    field_kind    CHAR(1)       NOT NULL,   -- R required, C conditional, S system-managed
    PRIMARY KEY (profile_no, display_label)
);


-- 270 field-dictionary rows (Sheet1), ids as the sheet has them.
INSERT #field_def
    (field_definition_id, field_key, display_label, group_code, data_type_code, lookup_source, validation_rule_text, description, is_system_mandatory, is_system_field, storage_kind, column_name, sensitivity_code, display_order, definition_version, effective_from, effective_to, status_code, is_custom)
