-- =====================================================================
-- 3. Validate the staged data against the live masters, BEFORE deleting
--    anything. Every check below failing means nothing has changed yet.
-- =====================================================================
DECLARE @bad NVARCHAR(MAX);

SELECT @bad = STRING_AGG(f.group_code, N', ')
FROM (SELECT DISTINCT group_code FROM #field_def) f
WHERE NOT EXISTS (SELECT 1 FROM grac_practice.asset_field_group_master g WHERE g.group_code = f.group_code);
IF @bad IS NOT NULL
BEGIN
    SET @msg = N'ABORT (502): dictionary group code(s) not in asset_field_group_master: ' + @bad;
    RAISERROR(@msg, 16, 1);
    RETURN;
END

SET @bad = NULL;
SELECT @bad = STRING_AGG(f.data_type_code, N', ')
FROM (SELECT DISTINCT data_type_code FROM #field_def) f
WHERE NOT EXISTS (SELECT 1 FROM grac_practice.asset_field_data_type_master t WHERE t.data_type_code = f.data_type_code);
IF @bad IS NOT NULL
BEGIN
    SET @msg = N'ABORT (502): data type code(s) not in asset_field_data_type_master: ' + @bad;
    RAISERROR(@msg, 16, 1);
    RETURN;
END

-- Every label the Asset Types sheet references must be a dictionary label.
SET @bad = NULL;
SELECT @bad = STRING_AGG(x.display_label, N' | ')
FROM (SELECT DISTINCT TOP (20) pf.display_label
        FROM #profile_field pf
       WHERE NOT EXISTS (SELECT 1 FROM #field_def d WHERE d.display_label = pf.display_label)) x;
IF @bad IS NOT NULL
BEGIN
    SET @msg = N'ABORT (502): label(s) in the Asset Types sheet are not in the dictionary: ' + @bad;
    RAISERROR(@msg, 16, 1);
    RETURN;
END

-- Any OTHER table still pointing at the TEMPLATE tables would make the
-- delete fail halfway. The known referrers are the template's own
-- children, its self-reference, and organization_dependency_asset
-- (handled by @clear_asset_template_links); anything else is named here
-- before the transaction starts rather than surfacing as Msg 547 inside
-- it, which is how fk_pm_org_asset_template was first found.
SET @bad = NULL;
SELECT @bad = STRING_AGG(QUOTENAME(SCHEMA_NAME(t.schema_id)) + N'.' + QUOTENAME(t.name)
                         + N' (' + c.name + N')', N', ')
FROM sys.foreign_keys fk
JOIN sys.tables t ON t.object_id = fk.parent_object_id
JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id
JOIN sys.columns c ON c.object_id = fkc.parent_object_id AND c.column_id = fkc.parent_column_id
WHERE fk.referenced_object_id IN (OBJECT_ID('grac_practice.asset_form_template'),
                                  OBJECT_ID('grac_practice.asset_form_template_section'),
                                  OBJECT_ID('grac_practice.asset_form_template_field'),
                                  OBJECT_ID('grac_practice.asset_form_template_rule'))
  AND t.name NOT IN (N'asset_form_template', N'asset_form_template_section',
                     N'asset_form_template_field', N'asset_form_template_rule',
                     N'asset_form_template_rule_condition', N'organization_dependency_asset');
IF @bad IS NOT NULL
BEGIN
    SET @msg = N'ABORT (502): table(s) reference the asset form template tables and this script does not clear them: '
             + @bad + N'. Clear them first, or extend section 4a.';
    RAISERROR(@msg, 16, 1);
    RETURN;
END

-- Any OTHER table still pointing at the dictionary would make the
-- reload fail halfway. Named here so the operator sees it before the
-- transaction starts, rather than as an FK error inside it.
SET @bad = NULL;
SELECT @bad = STRING_AGG(QUOTENAME(SCHEMA_NAME(t.schema_id)) + N'.' + QUOTENAME(t.name), N', ')
FROM sys.foreign_keys fk
JOIN sys.tables t ON t.object_id = fk.parent_object_id
WHERE fk.referenced_object_id = OBJECT_ID('grac_practice.asset_field_definition')
  AND t.name NOT IN (N'asset_form_template_field', N'asset_form_template_rule',
                     N'asset_form_template_rule_condition', N'asset_field_value');
IF @bad IS NOT NULL
BEGIN
    SET @msg = N'ABORT (502): table(s) reference asset_field_definition and this script does not clear them: '
             + @bad + N'. Clear them first, or extend section 4a.';
    RAISERROR(@msg, 16, 1);
    RETURN;
END

-- The organizations that get templates.
CREATE TABLE #org (organization_id BIGINT NOT NULL PRIMARY KEY);
INSERT #org (organization_id)
SELECT organization_id
FROM grac_practice.organization
WHERE status = N'Active'
  AND (@organization_id IS NULL OR organization_id = @organization_id);

IF NOT EXISTS (SELECT 1 FROM #org)
BEGIN
    RAISERROR('ABORT (502): no Active organization matched. Nothing was changed.', 16, 1);
    RETURN;
END

-- Counts go through variables: PRINT accepts only a scalar expression, and
-- a subquery inside it is a parse error (Msg 1046), not a run-time one --
-- it would stop the whole batch from compiling.
DECLARE @c_fields INT, @c_cats INT, @c_subs INT, @c_types INT, @c_profiles INT, @c_orgs INT;
SELECT @c_fields   = COUNT(*)                   FROM #field_def;
SELECT @c_cats     = COUNT(*)                   FROM #category;
SELECT @c_subs     = COUNT(*)                   FROM #subcategory;
SELECT @c_types    = COUNT(*)                   FROM #asset_type;
SELECT @c_profiles = COUNT(DISTINCT profile_no) FROM #profile_field;
SELECT @c_orgs     = COUNT(*)                   FROM #org;

PRINT CONCAT('502: staged  ', @c_fields, ' field definitions, ', @c_cats, ' categories, ',
             @c_subs, ' subcategories, ', @c_types, ' asset types, ', @c_profiles, ' label sets.');
PRINT CONCAT('502: target organizations: ', @c_orgs);

-- What this run is about to do, before it does any of it.
DECLARE @c_existing_templates INT, @c_asset_links INT;
SELECT @c_existing_templates = COUNT(*) FROM grac_practice.asset_form_template;
SELECT @c_asset_links = COUNT(*) FROM grac_practice.organization_dependency_asset WHERE template_id IS NOT NULL;

PRINT CONCAT('502: existing form templates to be deleted: ', @c_existing_templates);
PRINT CONCAT('502: assets whose template link will be cleared: ', @c_asset_links);
PRINT CONCAT('502: about to write ', @c_types * @c_orgs, ' templates and roughly ',
             47249 * @c_orgs, ' template field rows -- one transaction, so expect it to take a while.');

IF @c_asset_links > 0 AND @clear_asset_template_links = 0
BEGIN
    SET @msg = N'ABORT (502): ' + CAST(@c_asset_links AS NVARCHAR(20))
             + N' asset(s) still point at a form template through organization_dependency_asset.template_id. '
             + N'Deleting the templates requires clearing that link. Nothing was changed. '
             + N'Set @clear_asset_template_links = 1 to clear it.';
    RAISERROR(@msg, 16, 1);
    RETURN;
END

-- =====================================================================
-- 4. The load -- one transaction
-- =====================================================================
DECLARE @status_id          INT = grac_practice.fn_get_entity_status_id(N'AssetFormTemplate', @template_status);
DECLARE @is_active_version  BIT = CASE WHEN @template_status = N'ACTIVE' THEN 1 ELSE 0 END;
DECLARE @is_working_version BIT = CASE WHEN @template_status = N'ACTIVE' THEN 0 ELSE 1 END;
DECLARE @now DATETIME2 = SYSUTCDATETIME();
DECLARE @n_templates INT = 0, @n_sections INT = 0, @n_fields INT = 0;

BEGIN TRAN;

-- ---- 4a. every existing form template, all organizations -----------
-- An asset records the template version it was registered with
-- (organization_dependency_asset.template_id, 428). That is the only
-- foreign key into these tables from outside, and it has to be cleared
-- before the templates can go. The column is nullable; nothing else about
-- the asset row is touched.
UPDATE grac_practice.organization_dependency_asset
   SET template_id = NULL, updated_by = @actor, updated_dt = @now
 WHERE template_id IS NOT NULL;
PRINT CONCAT('502: asset template links cleared: ', @@ROWCOUNT);

-- source_template_id is a self-reference, so it is broken before the
-- rows are deleted.
UPDATE grac_practice.asset_form_template SET source_template_id = NULL WHERE source_template_id IS NOT NULL;

IF OBJECT_ID('grac_practice.asset_form_template_rule_condition','U') IS NOT NULL
    DELETE FROM grac_practice.asset_form_template_rule_condition;
IF OBJECT_ID('grac_practice.asset_form_template_rule','U') IS NOT NULL
    DELETE FROM grac_practice.asset_form_template_rule;

DELETE FROM grac_practice.asset_form_template_field;
DELETE FROM grac_practice.asset_form_template_section;
DELETE FROM grac_practice.asset_form_template;
PRINT '502: existing asset form templates cleared (all organizations).';

-- entity_state_transition_log is deliberately NOT touched. It is the
-- framework's immutable history (035); template_id is IDENTITY and keeps
-- climbing, so old entries can never be confused with the new ones.

-- ---- 4b. the field dictionary --------------------------------------
IF OBJECT_ID('grac_practice.asset_field_value','U') IS NOT NULL
   AND @force_delete_asset_values = 1
BEGIN
    DELETE FROM grac_practice.asset_field_value;
    PRINT '502: asset_field_value cleared (@force_delete_asset_values = 1).';
END

DELETE FROM grac_practice.asset_field_definition;
DBCC CHECKIDENT ('grac_practice.asset_field_definition', RESEED, 0) WITH NO_INFOMSGS;

SET IDENTITY_INSERT grac_practice.asset_field_definition ON;
INSERT grac_practice.asset_field_definition
    (field_definition_id, field_key, display_label, field_group_id, data_type_code, lookup_source,
     validation_rule_text, description, is_system_mandatory, is_system_field, storage_kind,
     column_name, sensitivity_code, display_order, definition_version, effective_from,
     effective_to, status_code, is_custom, entered_by, entered_dt)
SELECT f.field_definition_id, f.field_key, f.display_label, g.field_group_id, f.data_type_code,
       f.lookup_source, f.validation_rule_text, f.description, f.is_system_mandatory,
       f.is_system_field, f.storage_kind, f.column_name, f.sensitivity_code, f.display_order,
       f.definition_version, f.effective_from, f.effective_to, f.status_code, f.is_custom,
       @actor, @now
FROM #field_def f
JOIN grac_practice.asset_field_group_master g ON g.group_code = f.group_code
ORDER BY f.field_definition_id;
SET IDENTITY_INSERT grac_practice.asset_field_definition OFF;
DBCC CHECKIDENT ('grac_practice.asset_field_definition', RESEED) WITH NO_INFOMSGS;
SELECT @c_fields = COUNT(*) FROM grac_practice.asset_field_definition;
PRINT CONCAT('502: field dictionary reloaded: ', @c_fields, ' rows.');

-- ---- 4c. taxonomy: retire the old values, add the sheet's ----------
-- Nothing is deleted. The old ids stay valid for every asset, event
-- scope mapping and catalog row that already points at them; is_active = 0
-- only takes them out of the pickers.
UPDATE grac_practice.dependency_asset_type_master
   SET is_active = 0, updated_by = @actor, updated_dt = @now WHERE is_active = 1;
UPDATE grac_practice.dependency_asset_subcategory_master
   SET is_active = 0, updated_by = @actor, updated_dt = @now WHERE is_active = 1;
UPDATE grac_practice.dependency_asset_category_master
   SET is_active = 0, updated_by = @actor, updated_dt = @now WHERE is_active = 1;

MERGE grac_practice.dependency_asset_category_master AS t
USING (SELECT category_code, category_name, display_order FROM #category) AS s
   ON t.asset_category_code = s.category_code
WHEN MATCHED THEN UPDATE SET
    asset_category_name = s.category_name, display_order = s.display_order,
    is_active = 1, updated_by = @actor, updated_dt = @now
WHEN NOT MATCHED BY TARGET THEN
    INSERT (asset_category_code, asset_category_name, display_order, is_active, entered_by, entered_dt)
    VALUES (s.category_code, s.category_name, s.display_order, 1, @actor, @now);

MERGE grac_practice.dependency_asset_subcategory_master AS t
USING (SELECT sc.subcategory_code, sc.subcategory_name, sc.display_order, c.asset_category_id
         FROM #subcategory sc
         JOIN #category ct ON ct.category_name = sc.category_name
         JOIN grac_practice.dependency_asset_category_master c ON c.asset_category_code = ct.category_code) AS s
   ON t.subcategory_code = s.subcategory_code
WHEN MATCHED THEN UPDATE SET
    asset_category_id = s.asset_category_id, subcategory_name = s.subcategory_name,
    display_order = s.display_order, is_active = 1, updated_by = @actor, updated_dt = @now
WHEN NOT MATCHED BY TARGET THEN
    INSERT (asset_category_id, subcategory_code, subcategory_name, display_order, is_active, entered_by, entered_dt)
    VALUES (s.asset_category_id, s.subcategory_code, s.subcategory_name, s.display_order, 1, @actor, @now);

MERGE grac_practice.dependency_asset_type_master AS t
USING (SELECT a.asset_type_code, a.asset_type_name, a.display_order, sub.subcategory_id
         FROM #asset_type a
         JOIN #subcategory sc ON sc.category_name = a.category_name AND sc.subcategory_name = a.subcategory_name
         JOIN grac_practice.dependency_asset_subcategory_master sub ON sub.subcategory_code = sc.subcategory_code) AS s
   ON t.asset_type_code = s.asset_type_code
WHEN MATCHED THEN UPDATE SET
    subcategory_id = s.subcategory_id, asset_type_name = s.asset_type_name,
    display_order = s.display_order, is_active = 1, updated_by = @actor, updated_dt = @now
WHEN NOT MATCHED BY TARGET THEN
    INSERT (subcategory_id, asset_type_code, asset_type_name, display_order, is_active, entered_by, entered_dt)
    VALUES (s.subcategory_id, s.asset_type_code, s.asset_type_name, s.display_order, 1, @actor, @now);

SELECT @c_cats  = COUNT(*) FROM grac_practice.dependency_asset_category_master    WHERE is_active = 1;
SELECT @c_subs  = COUNT(*) FROM grac_practice.dependency_asset_subcategory_master WHERE is_active = 1;
SELECT @c_types = COUNT(*) FROM grac_practice.dependency_asset_type_master        WHERE is_active = 1;
PRINT CONCAT('502: taxonomy active now: ', @c_cats, ' categories, ',
             @c_subs, ' subcategories, ', @c_types, ' asset types.');

-- ---- 4d. one template per organization per asset type --------------
CREATE TABLE #tmpl (
    template_id     BIGINT NOT NULL PRIMARY KEY,
    organization_id BIGINT NOT NULL,
    asset_type_id   INT    NOT NULL
);

INSERT grac_practice.asset_form_template
    (organization_id, asset_type_id, template_name, version_no, current_status_id, approval_required,
     template_owner_employee_id, effective_from, change_reason, is_active_version, is_working_version,
     activated_by, activated_dt, entered_by, entered_dt)
OUTPUT inserted.template_id, inserted.organization_id, inserted.asset_type_id INTO #tmpl
SELECT o.organization_id, m.asset_type_id, LEFT(m.asset_type_name, 200), 1, @status_id, 1,
       NULL, CAST(@now AS DATE),
       N'Loaded from AssetFields_Mapping_v1.0.xlsx (502).',
       @is_active_version, @is_working_version,
       CASE WHEN @template_status = N'ACTIVE' THEN @actor END,
       CASE WHEN @template_status = N'ACTIVE' THEN @now   END,
       @actor, @now
FROM #org o
CROSS JOIN #asset_type a
JOIN grac_practice.dependency_asset_type_master m ON m.asset_type_code = a.asset_type_code;
SET @n_templates = @@ROWCOUNT;

-- ---- 4e. sections: one per dictionary group that has fields --------
CREATE TABLE #sect (
    section_id  BIGINT       NOT NULL PRIMARY KEY,
    template_id BIGINT       NOT NULL,
    section_key NVARCHAR(60) NOT NULL,
    UNIQUE (template_id, section_key)
);

INSERT grac_practice.asset_form_template_section
    (template_id, section_key, section_label, tab_label, layout_columns, display_order, is_system, entered_by, entered_dt)
OUTPUT inserted.section_id, inserted.template_id, inserted.section_key INTO #sect
SELECT t.template_id, g.group_code, g.group_name, g.group_name, 2, g.display_order, 0, @actor, @now
FROM #tmpl t
JOIN grac_practice.dependency_asset_type_master m ON m.asset_type_id   = t.asset_type_id
JOIN #asset_type a                               ON a.asset_type_code = m.asset_type_code
JOIN #profile_field pf                           ON pf.profile_no     = a.profile_no
JOIN #field_def d                                ON d.display_label   = pf.display_label
JOIN grac_practice.asset_field_group_master g    ON g.group_code      = d.group_code
GROUP BY t.template_id, g.group_code, g.group_name, g.display_order;
SET @n_sections = @@ROWCOUNT;

-- AUDIT_HISTORY, exactly as sp_asset_form_template_create adds it.
INSERT grac_practice.asset_form_template_section
    (template_id, section_key, section_label, layout_columns, display_order, is_system, entered_by, entered_dt)
SELECT t.template_id, N'AUDIT_HISTORY', N'Audit History', 1, 9999, 1, @actor, @now
FROM #tmpl t;
SET @n_sections = @n_sections + @@ROWCOUNT;

-- ---- 4f. the fields ------------------------------------------------
-- required         -> visible, mandatory
-- conditional      -> visible, optional
-- system-managed   -> visible, optional, read-only
-- plus 420's own rule: a data type that is not user-entered is read-only
-- whichever column the label came from.
--
-- One override, and the reason for it. 420 marks ten fields
-- is_system_mandatory (the BRD 5.1.17 baseline) and states that a
-- template must carry them visible AND mandatory and cannot weaken them
-- (5.2.1 / 5.2.21); sp_asset_form_template_readiness checks it. Eight of
-- the ten are in the sheet's required column. The other two -- Asset ID
-- (data type AUTO) and Asset status (storage SYSTEM) -- are in its
-- system-managed column, which is correct in itself: the application
-- fills them. Left as the sheet has them, every one of the 318 templates
-- would fail readiness. So is_mandatory is forced on for any
-- is_system_mandatory field, exactly as sp_asset_form_template_create
-- does, and those two come out mandatory and read-only -- again the same
-- as that procedure, because their data types are not user-entered.
-- Nothing else in the sheet is overridden.
INSERT grac_practice.asset_form_template_field
    (template_id, field_definition_id, section_id, display_order,
     is_visible, is_mandatory, is_read_only, entered_by, entered_dt)
SELECT t.template_id, def.field_definition_id, s.section_id, d.display_order,
       1,
       CASE WHEN pf.field_kind = 'R' OR d.is_system_mandatory = 1 THEN 1 ELSE 0 END,
       CASE WHEN pf.field_kind = 'S' OR dt.is_user_entered = 0 THEN 1 ELSE 0 END,
       @actor, @now
FROM #tmpl t
JOIN grac_practice.dependency_asset_type_master m ON m.asset_type_id   = t.asset_type_id
JOIN #asset_type a                               ON a.asset_type_code = m.asset_type_code
JOIN #profile_field pf                           ON pf.profile_no     = a.profile_no
JOIN #field_def d                                ON d.display_label   = pf.display_label
JOIN grac_practice.asset_field_definition def    ON def.field_key     = d.field_key
JOIN grac_practice.asset_field_data_type_master dt ON dt.data_type_code = d.data_type_code
JOIN #sect s ON s.template_id = t.template_id AND s.section_key = d.group_code;
SET @n_fields = @@ROWCOUNT;

-- ---- 4g. audit ------------------------------------------------------
INSERT grac_practice.entity_state_transition_log
    (entity_type, entity_id, from_status_id, to_status_id, actor_employee_id, actor_role_code,
     reason_code, reason_text, transitioned_at)
SELECT N'AssetFormTemplate', t.template_id, NULL, @status_id, NULL, NULL,
       N'BULK_LOAD', N'Loaded from AssetFields_Mapping_v1.0.xlsx (502).', @now
FROM #tmpl t;

INSERT grac_practice.practice_audit_trace
    (entity_type, entity_id, action_type, after_json, status, entered_by)
SELECT N'asset-form-template', t.template_id, N'CREATE',
       (SELECT t.organization_id AS organizationId, t.asset_type_id AS assetTypeId,
               1 AS versionNo, @template_status AS statusCode, N'502' AS loadedBy
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
       N'Active', @actor
FROM #tmpl t;

COMMIT;

PRINT CONCAT('502: templates ', @n_templates, ', sections ', @n_sections, ', template fields ', @n_fields, '.');

-- =====================================================================
-- 5. Verification
-- =====================================================================
PRINT '--- 502 verification ---';

SELECT (SELECT COUNT(*) FROM grac_practice.asset_field_definition)                                AS field_definitions,
       (SELECT MIN(field_definition_id) FROM grac_practice.asset_field_definition)                AS first_id,
       (SELECT MAX(field_definition_id) FROM grac_practice.asset_field_definition)                AS last_id,
       (SELECT COUNT(*) FROM grac_practice.dependency_asset_category_master    WHERE is_active = 1) AS active_categories,
       (SELECT COUNT(*) FROM grac_practice.dependency_asset_subcategory_master WHERE is_active = 1) AS active_subcategories,
       (SELECT COUNT(*) FROM grac_practice.dependency_asset_type_master        WHERE is_active = 1) AS active_asset_types,
       (SELECT COUNT(*) FROM grac_practice.asset_form_template)                                   AS templates,
       (SELECT COUNT(*) FROM grac_practice.asset_form_template_section)                           AS sections,
       (SELECT COUNT(*) FROM grac_practice.asset_form_template_field)                              AS template_fields;

-- Expected, computed from the sheet before this file was written:
--   field_definitions 270, first_id 1, last_id 270
--   active_categories 11, active_subcategories 52, active_asset_types 318
--   per target organization: 318 templates, 3,935 sections
--     (3,617 group sections + 318 AUDIT_HISTORY), 47,249 template fields,
--     of which 11,349 mandatory and 5,562 read-only.
--   So for 2 active organizations: 636 templates, 7,870 sections,
--     94,498 template fields.

SELECT o.organization_id,
       COUNT(DISTINCT tpl.template_id)   AS templates,
       COUNT(DISTINCT sec.section_id)    AS sections,
       COUNT(fld.template_field_id)      AS fields,
       SUM(CASE WHEN fld.is_mandatory = 1 THEN 1 ELSE 0 END) AS mandatory_fields,
       SUM(CASE WHEN fld.is_read_only  = 1 THEN 1 ELSE 0 END) AS read_only_fields
FROM #org o
LEFT JOIN grac_practice.asset_form_template         tpl ON tpl.organization_id = o.organization_id
LEFT JOIN grac_practice.asset_form_template_section sec ON sec.template_id     = tpl.template_id
LEFT JOIN grac_practice.asset_form_template_field   fld ON fld.template_id     = tpl.template_id
GROUP BY o.organization_id
ORDER BY o.organization_id;

-- Every asset type of every target organization must have exactly one
-- template, and no template may be short of a field the sheet listed.
SELECT 'asset types with no template' AS check_name, COUNT(*) AS offending_rows
FROM #org o
CROSS JOIN #asset_type a
JOIN grac_practice.dependency_asset_type_master m ON m.asset_type_code = a.asset_type_code
WHERE NOT EXISTS (SELECT 1 FROM grac_practice.asset_form_template tpl
                   WHERE tpl.organization_id = o.organization_id AND tpl.asset_type_id = m.asset_type_id)
UNION ALL
SELECT 'templates whose field count differs from the sheet', COUNT(*)
FROM (
    SELECT tpl.template_id,
           (SELECT COUNT(*) FROM grac_practice.asset_form_template_field f WHERE f.template_id = tpl.template_id) AS got,
           (SELECT COUNT(*) FROM #profile_field pf WHERE pf.profile_no = a.profile_no)                            AS want
    FROM grac_practice.asset_form_template tpl
    JOIN grac_practice.dependency_asset_type_master m ON m.asset_type_id   = tpl.asset_type_id
    JOIN #asset_type a                               ON a.asset_type_code = m.asset_type_code
) x
WHERE x.got <> x.want
UNION ALL
SELECT 'system-mandatory fields missing from a template', COUNT(*)
FROM grac_practice.asset_form_template tpl
CROSS JOIN grac_practice.asset_field_definition d
WHERE d.is_system_mandatory = 1 AND d.status_code = N'ACTIVE' AND d.is_system_field = 0
  AND NOT EXISTS (SELECT 1 FROM grac_practice.asset_form_template_field f
                   WHERE f.template_id = tpl.template_id
                     AND f.field_definition_id = d.field_definition_id
                     AND f.is_visible = 1 AND f.is_mandatory = 1);
-- All three counts must be 0.

-- A spot check: one asset type, its sections and how many fields in each.
SELECT TOP (20) m.asset_type_name, sec.section_key, sec.section_label, COUNT(fld.template_field_id) AS fields
FROM grac_practice.asset_form_template tpl
JOIN grac_practice.dependency_asset_type_master m   ON m.asset_type_id = tpl.asset_type_id
JOIN grac_practice.asset_form_template_section sec  ON sec.template_id = tpl.template_id
LEFT JOIN grac_practice.asset_form_template_field fld ON fld.section_id = sec.section_id
WHERE tpl.template_id = (SELECT MIN(template_id) FROM grac_practice.asset_form_template)
GROUP BY m.asset_type_name, sec.section_key, sec.section_label, sec.display_order
ORDER BY sec.display_order;

DROP TABLE #profile_field;
DROP TABLE #asset_type;
DROP TABLE #subcategory;
DROP TABLE #category;
DROP TABLE #field_def;
DROP TABLE #sect;
DROP TABLE #tmpl;
DROP TABLE #org;

PRINT '502: done.';
GO
